.wave-content {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  z-index: 10;
  text-align: center;
  color: #ffffff;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  pointer-events: none; /* ટચ ઇવેન્ટ્સને 3D બેકગ્રાઉન્ડ સુધી જવા દેવા માટે */
  background: rgba(10, 10, 10, 0.4);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 20px;
  padding: 30px;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.5);
}
.wave-title {
  font-size: 36px;
  font-weight: bold;
  margin: 0 0 10px 0;
  color: #67e8f9;
  animation: waveGlow 2s ease-in-out infinite alternate;
}
.wave-subtitle {
  font-size: 16px;
  color: #cbd5e1;
  margin: 0;
}
@keyframes waveGlow {
  from { text-shadow: 0 0 5px #fff, 0 0 10px #00e6e6, 0 0 15px #00e6e6; }
  to { text-shadow: 0 0 10px #fff, 0 0 20px #00e6e6, 0 0 30px #00e6e6; }
}

