const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;overflow:hidden;background:#051b2c;';

// ગ્લાસમોરફિઝમ કન્ટેન્ટ ઉમેરવું
c.innerHTML = `
  <div class="wave-content">
    <h1 class="wave-title">Ultra Max 3D Waves</h1>
    <p class="wave-subtitle">ટચ કરીને લહેરોની દિશા બદલો</p>
  </div>
`;

// Vanta.js ચાલુ કરવાનું ફંક્શન
function initVanta() {
  if (window.vantaEffect) window.vantaEffect.destroy(); // જૂનું એનિમેશન હોય તો ક્લિયર કરવું
  window.vantaEffect = VANTA.WAVES({
    el: c,
    mouseControls: true,
    touchControls: true,
    gyroControls: false,
    minHeight: 200.00,
    minWidth: 200.00,
    scale: 1.00,
    scaleMobile: 1.00,
    color: 0x051b2c, // ડાર્ક બ્લુ કલર 
    shininess: 30.00,
    waveHeight: 15.00,
    waveSpeed: 0.80, // સ્મૂથ સ્પીડ
    zoom: 1.0
  });
}

// ડાયનેમિક લાઈબ્રેરી લોડર (HTML માં સ્ક્રિપ્ટ એડ કર્યા વગર)
if (typeof THREE === 'undefined') {
  const script1 = document.createElement('script');
  script1.src = 'https://cdnjs.cloudflare.com/ajax/libs/three.js/r134/three.min.js';
  document.head.appendChild(script1);
  script1.onload = () => {
    const script2 = document.createElement('script');
    script2.src = 'https://cdn.jsdelivr.net/npm/vanta@latest/dist/vanta.waves.min.js';
    document.head.appendChild(script2);
    script2.onload = initVanta;
  };
} else if (typeof VANTA === 'undefined') {
  const script2 = document.createElement('script');
  script2.src = 'https://cdn.jsdelivr.net/npm/vanta@latest/dist/vanta.waves.min.js';
  document.head.appendChild(script2);
  script2.onload = initVanta;
} else {
  initVanta();
}
